def _separable(transform):
    """
    Calculate the separability of outputs.

    Parameters
    ----------
    transform : `astropy.modeling.Model`
        A transform (usually a compound model).

    Returns :
    is_separable : ndarray of dtype np.bool
        An array of shape (transform.n_outputs,) of boolean type
        Each element represents the separablity of the corresponding output.
    """
    if (transform_matrix := transform._calculate_separability_matrix()) is not NotImplemented:
        return transform_matrix
    elif isinstance(transform, CompoundModel):
        sepleft = _separable(transform.left)
        sepright = _separable(transform.right)
        return _operators[transform.op](sepleft, sepright)
    elif isinstance(transform, Model):
        return _coord_matrix(transform, 'left', transform.n_outputs)

def iter_modules_and_files(modules, extra_files):
    """Iterate through all modules needed to be watched."""
    sys_file_paths = []
    for module in modules:
        # During debugging (with PyDev) the 'typing.io' and 'typing.re' objects
        # are added to sys.modules, however they are types not modules and so
        # cause issues here.
        if not isinstance(module, ModuleType) or getattr(module, '__spec__', None) is None:
            continue
        spec = module.__spec__
        # Modules could be loaded from places without a concrete location. If
        # this is the case, skip them.
        if spec.has_location:
            origin = spec.loader.archive if isinstance(spec.loader, zipimporter) else spec.origin
            sys_file_paths.append(origin)

    results = set()
    for filename in itertools.chain(sys_file_paths, extra_files):
        if not filename:
            continue
        path = pathlib.Path(filename)
        if not path.exists():
            # The module could have been removed, don't fail loudly if this
            # is the case.
            continue
        results.add(path.resolve().absolute())
    return frozenset(results)

def snapshot_files(self):
    # watched_files may produce duplicate paths if globs overlap.
    seen_files = set()
    for file in self.watched_files():
        if file in seen_files:
            continue
        try:
            mtime = file.stat().st_mtime
        except OSError:
            # This is thrown when the file does not exist.
            continue
        seen_files.add(file)
        yield file, mtime

def watched_files(self, include_globs=True):
    """
    Yield all files that need to be watched, including module files and
    files within globs.
    """
    yield from iter_all_python_module_files()
    yield from self.extra_files
    if include_globs:
        for directory, patterns in self.directory_globs.items():
            for pattern in patterns:
                yield from directory.glob(pattern)

def serialize(self):
    enum_class = self.value.__class__
    module = enum_class.__module__
    v_string, v_imports = serializer_factory(self.value.value).serialize()
    imports = {'import %s' % module, *v_imports}
    return "%s.%s(%s)" % (module, enum_class.__name__, v_string), imports

def resolve(self, path):
    match = self.pattern.match(path)
    if match:
        new_path, args, kwargs = match
        # Pass any extra_kwargs as **kwargs.
        kwargs.update(self.default_args)
        return ResolverMatch(self.callback, args, kwargs, self.pattern.name, route=str(self.pattern))

def match(self, path):
    match = self.regex.search(path)
    if match:
        # If there are any named groups, use those as kwargs, ignoring
        # non-named groups. Otherwise, pass all non-named arguments as
        # positional arguments.
        kwargs = {k: v for k, v in match.groupdict().items() if v is not None}
        args = () if kwargs else match.groups()
        return path[match.end():], args, kwargs
    return None

def state_forwards(self, app_label, state):
    model_state = state.models[app_label, self.model_name_lower]
    # Rename the field
    fields = model_state.fields
    found = False
    delay = True
    for index, (name, field) in enumerate(fields):
        if not found and name == self.old_name:
            fields[index] = (self.new_name, field)
            found = True
        # Fix from_fields to refer to the new field.
        from_fields = getattr(field, 'from_fields', None)
        if from_fields:
            field.from_fields = tuple([
                self.new_name if from_field_name == self.old_name else from_field_name
                for from_field_name in from_fields
            ])
        # Delay rendering of relationships if it's not a relational
        # field and not referenced by a foreign key.
        delay = delay and (
            not field.is_relation and
            not is_referenced_by_foreign_key(state, self.model_name_lower, field, self.name)
        )
    if not found:
        raise FieldDoesNotExist(
            "%s.%s has no field named '%s'" % (app_label, self.model_name, self.old_name)
        )
    # Fix index/unique_together to refer to the new field
    options = model_state.options
    for option in ('index_together', 'unique_together'):
        if option in options:
            options[option] = [
                [self.new_name if n == self.old_name else n for n in together]
                for together in options[option]
            ]
    # Fix to_fields to refer to the new field.
    model_tuple = app_label, self.model_name_lower
    for (model_app_label, model_name), model_state in state.models.items():
        for index, (name, field) in enumerate(model_state.fields):
            remote_field = field.remote_field
            if remote_field:
                remote_model_tuple = self._get_model_tuple(
                    remote_field.model, model_app_label, model_name
                )
                if remote_model_tuple == model_tuple:
                    if getattr(remote_field, 'field_name', None) == self.old_name:
                        remote_field.field_name = self.new_name
                    to_fields = getattr(field, 'to_fields', None)
                    if to_fields:
                        field.to_fields = tuple([
                            self.new_name if to_field_name == self.old_name else to_field_name
                            for to_field_name in to_fields
                        ])
    state.reload_model(app_label, self.model_name_lower, delay=delay)

def deconstruct(self):
    name, path, args, kwargs = super().deconstruct()
    kwargs['on_delete'] = self.remote_field.on_delete
    kwargs['from_fields'] = self.from_fields
    kwargs['to_fields'] = self.to_fields

    if self.remote_field.parent_link:
        kwargs['parent_link'] = self.remote_field.parent_link
    # Work out string form of "to"
    if isinstance(self.remote_field.model, str):
        kwargs['to'] = self.remote_field.model
    else:
        kwargs['to'] = "%s.%s" % (
            self.remote_field.model._meta.app_label,
            self.remote_field.model._meta.object_name,
        )
    # If swappable is True, then see if we're actually pointing to the target
    # of a swap.
    swappable_setting = self.swappable_setting
    if swappable_setting is not None:
        # If it's already a settings reference, error
        if hasattr(kwargs['to'], "setting_name"):
            if kwargs['to'].setting_name != swappable_setting:
                raise ValueError(
                    "Cannot deconstruct a ForeignKey pointing to a model "
                    "that is swapped in place of more than one model (%s and %s)"
                    % (kwargs['to'].setting_name, swappable_setting)
                )
        # Set it
        kwargs['to'] = SettingsReference(
            kwargs['to'],
            swappable_setting,
        )
    return name, path, args, kwargs

def deep_deconstruct(self, obj):
    """
    Recursive deconstruction for a field and its arguments.
    Used for full comparison for rename/alter; sometimes a single-level
    deconstruction will not compare correctly.
    """
    if isinstance(obj, list):
        return [self.deep_deconstruct(value) for value in obj]
    elif isinstance(obj, tuple):
        return tuple(self.deep_deconstruct(value) for value in obj)
    elif isinstance(obj, dict):
        return {
            key: self.deep_deconstruct(value)
            for key, value in obj.items()
        }
    elif isinstance(obj, functools.partial):
        return (obj.func, self.deep_deconstruct(obj.args), self.deep_deconstruct(obj.keywords))
    elif isinstance(obj, COMPILED_REGEX_TYPE):
        return RegexObject(obj)
    elif isinstance(obj, type):
        # If this is a type that implements 'deconstruct' as an instance method,
        # avoid treating this as being deconstructible itself - see #22951
        return obj
    elif hasattr(obj, 'deconstruct'):
        deconstructed = obj.deconstruct()
        if isinstance(obj, models.Field):
            # we have a field which also returns a name
            deconstructed = deconstructed[1:]
        path, args, kwargs = deconstructed
        return (
            path,
            [self.deep_deconstruct(value) for value in args],
            {
                key: self.deep_deconstruct(value)
                for key, value in kwargs.items()
            },
        )
    else:
        return obj

def _check_constraints(cls, databases):
    errors = []
    for db in databases:
        if not router.allow_migrate_model(db, cls):
            continue
        connection = connections[db]
        if not (
            connection.features.supports_table_check_constraints or
            'supports_table_check_constraints' in cls._meta.required_db_features
        ) and any(
            isinstance(constraint, CheckConstraint)
            for constraint in cls._meta.constraints
        ):
            errors.append(
                checks.Warning(
                    '%s does not support check constraints.' % connection.display_name,
                    hint=(
                        "A constraint won't be created. Silence this "
                        "warning if you don't care about it."
                    ),
                    obj=cls,
                    id='models.W027',
                )
            )
        if not (
            connection.features.supports_partial_indexes or
            'supports_partial_indexes' in cls._meta.required_db_features
        ) and any(
            isinstance(constraint, UniqueConstraint) and constraint.condition is not None
            for constraint in cls._meta.constraints
        ):
            errors.append(
                checks.Warning(
                    '%s does not support unique constraints with '
                    'conditions.' % connection.display_name,
                    hint=(
                        "A constraint won't be created. Silence this "
                        "warning if you don't care about it."
                    ),
                    obj=cls,
                    id='models.W036',
                )
            )
        if not (
            connection.features.supports_deferrable_unique_constraints or
            'supports_deferrable_unique_constraints' in cls._meta.required_db_features
        ) and any(
            isinstance(constraint, UniqueConstraint) and constraint.deferrable is not None
            for constraint in cls._meta.constraints
        ):
            errors.append(
                checks.Warning(
                    '%s does not support deferrable unique constraints.'
                    % connection.display_name,
                    hint=(
                        "A constraint won't be created. Silence this "
                        "warning if you don't care about it."
                    ),
                    obj=cls,
                    id='models.W038',
                )
            )
    return errors

def _check_unique_together(cls):
    """Check the value of "unique_together" option."""
    if not isinstance(cls._meta.unique_together, (tuple, list)):
        return [
            checks.Error(
                "'unique_together' must be a list or tuple.",
                obj=cls,
                id='models.E010',
            )
        ]

    elif any(not isinstance(fields, (tuple, list)) for fields in cls._meta.unique_together):
        return [
            checks.Error(
                "All 'unique_together' elements must be lists or tuples.",
                obj=cls,
                id='models.E011',
            )
        ]

    else:
        errors = []
        for fields in cls._meta.unique_together:
            errors.extend(cls._check_local_fields(fields, "unique_together"))
        return errors

def _check_local_fields(cls, fields, option):
    from django.db import models

    # In order to avoid hitting the relation tree prematurely, we use our
    # own fields_map instead of using get_field()
    forward_fields_map = {}
    for field in cls._meta._get_fields(reverse=False):
        forward_fields_map[field.name] = field
        if hasattr(field, 'attname'):
            forward_fields_map[field.attname] = field

    errors = []
    for field_name in fields:
        try:
            field = forward_fields_map[field_name]
        except KeyError:
            errors.append(
                checks.Error(
                    "'%s' refers to the nonexistent field '%s'." % (
                        option, field_name,
                    ),
                    obj=cls,
                    id='models.E012',
                )
            )
        else:
            if isinstance(field.remote_field, models.ManyToManyRel):
                errors.append(
                    checks.Error(
                        "'%s' refers to a ManyToManyField '%s', but "
                        "ManyToManyFields are not permitted in '%s'." % (
                            option, field_name, option,
                        ),
                        obj=cls,
                        id='models.E013',
                    )
                )
            elif field not in cls._meta.local_fields:
                errors.append(
                    checks.Error(
                        "'%s' refers to field '%s' which is not local to model '%s'."
                        % (option, field_name, cls._meta.object_name),
                        hint="This issue may be caused by multi-table inheritance.",
                        obj=cls,
                        id='models.E016',
                    )
                )
    return errors

def __init__(self, message, code=None, params=None):
    """
    The `message` argument can be a single error, a list of errors, or a
    dictionary that maps field names to lists of errors. What we define as
    an "error" can be either a simple string or an instance of
    ValidationError with its message attribute set, and what we define as
    list or dictionary can be an actual `list` or `dict` or an instance
    of ValidationError with its `error_list` or `error_dict` attribute set.
    """
    super().__init__(message, code, params)

    if isinstance(message, ValidationError):
        if hasattr(message, 'error_dict'):
            message = message.error_dict
        elif not hasattr(message, 'message'):
            message = message.error_list
        else:
            message, code, params = message.message, message.code, message.params

    if isinstance(message, dict):
        self.error_dict = {}
        for field, messages in message.items():
            if not isinstance(messages, ValidationError):
                messages = ValidationError(messages)
            self.error_dict[field] = messages.error_list

    elif isinstance(message, list):
        self.error_list = []
        for message in message:
            # Normalize plain strings to instances of ValidationError.
            if not isinstance(message, ValidationError):
                message = ValidationError(message)
            if hasattr(message, 'error_dict'):
                self.error_list.extend(sum(message.error_dict.values(), []))
            else:
                self.error_list.extend(message.error_list)

    else:
        self.message = message
        self.code = code
        self.params = params
        self.error_list = [self]

def serialize_db_to_string(self):
    """
    Serialize all data in the database into a JSON string.
    Designed only for test runner usage; will not handle large
    amounts of data.
    """
    # Iteratively return every object for all models to serialize.
    def get_objects():
        from django.db.migrations.loader import MigrationLoader
        loader = MigrationLoader(self.connection)
        for app_config in apps.get_app_configs():
            if (
                app_config.models_module is not None and
                app_config.label in loader.migrated_apps and
                app_config.name not in settings.TEST_NON_SERIALIZED_APPS
            ):
                for model in app_config.get_models():
                    if (
                        model._meta.can_migrate(self.connection) and
                        router.allow_migrate_model(self.connection.alias, model)
                    ):
                        queryset = model._default_manager.using(
                            self.connection.alias,
                        ).order_by(model._meta.pk.name)
                        yield from queryset.iterator()
    # Serialize to a string
    out = StringIO()
    serializers.serialize("json", get_objects(), indent=None, stream=out)
    return out.getvalue()

class KeyTransformIsNull(lookups.IsNull):
    # key__isnull=False is the same as has_key='key'
    def as_oracle(self, compiler, connection):
        if not self.rhs:
            return HasKey(self.lhs.lhs, self.lhs.key_name).as_oracle(compiler, connection)
        return super().as_sql(compiler, connection)

    def as_sqlite(self, compiler, connection):
        if not self.rhs:
            return HasKey(self.lhs.lhs, self.lhs.key_name).as_sqlite(compiler, connection)
        return super().as_sql(compiler, connection)

def __repr__(self):
    return "ResolverMatch(func=%s, args=%s, kwargs=%s, url_name=%s, app_names=%s, namespaces=%s, route=%s)" % (
        self._func_path, self.args, self.kwargs, self.url_name,
        self.app_names, self.namespaces, self.route,
    )

def as_string(self):
    """Return a string of the file contents."""
    items = {
        "replaces_str": "",
        "initial_str": "",
    }

    imports = set()

    # Deconstruct operations
    operations = []
    for operation in self.migration.operations:
        operation_string, operation_imports = OperationWriter(operation).serialize()
        imports.update(operation_imports)
        operations.append(operation_string)
    items["operations"] = "\n".join(operations) + "\n" if operations else ""

    # Format dependencies and write out swappable dependencies right
    dependencies = []
    for dependency in self.migration.dependencies:
        if dependency[0] == "__setting__":
            dependencies.append("        migrations.swappable_dependency(settings.%s)," % dependency[1])
            imports.add("from django.conf import settings")
        else:
            dependencies.append("        %s," % self.serialize(dependency)[0])
    items["dependencies"] = "\n".join(dependencies) + "\n" if dependencies else ""

    # Format imports nicely, swapping imports of functions from migration files
    # for comments
    migration_imports = set()
    for line in list(imports):
        if re.match(r"^import (.*)\.\d+[^\s]*$", line):
            migration_imports.add(line.split("import")[1].strip())
            imports.remove(line)
            self.needs_manual_porting = True

    # django.db.migrations is always used, but models import may not be.
    # If models import exists, merge it with migrations import.
    if "from django.db import models" in imports:
        imports.discard("from django.db import models")
        imports.add("from django.db import migrations, models")
    else:
        imports.add("from django.db import migrations")

    # Sort imports by the package / module to be imported (the part after
    # "from" in "from ... import ..." or after "import" in "import ...").
    sorted_imports = sorted(imports, key=lambda i: i.split()[1])
    items["imports"] = "\n".join(sorted_imports) + "\n" if imports else ""
    if migration_imports:
        items["imports"] += (
            "\n\n# Functions from the following migrations need manual "
            "copying.\n# Move them and any dependencies into this file, "
            "then update the\n# RunPython operations to refer to the local "
            "versions:\n# %s"
        ) % "\n# ".join(sorted(migration_imports))
    # If there's a replaces, make a string for it
    if self.migration.replaces:
        items['replaces_str'] = "\n    replaces = %s\n" % self.serialize(self.migration.replaces)[0]
    # Hinting that goes into comment
    if self.include_header:
        items['migration_header'] = MIGRATION_HEADER_TEMPLATE % {
            'version': get_version(),
            'timestamp': now().strftime("%Y-%m-%d %H:%M"),
        }
    else:
        items['migration_header'] = ""

    if self.migration.initial:
        items['initial_str'] = "\n    initial = True\n"

    return MIGRATION_TEMPLATE % items

def deconstruct(self):
    kwargs = {
        'name': self.name,
        'fields': self.fields,
    }
    if self.options:
        kwargs['options'] = self.options
    if self.bases and self.bases != (models.Model,):
        kwargs['bases'] = self.bases
    if self.managers and self.managers != [('objects', models.Manager())]:
        kwargs['managers'] = self.managers
    return (
        self.__class__.__qualname__,
        [],
        kwargs
    )

def serialize(self):
    special_cases = [
        (models.Model, "models.Model", []),
        (type(None), 'type(None)', []),
    ]
    for case, string, imports in special_cases:
        if case is self.value:
            return string, set(imports)
    if hasattr(self.value, "__module__"):
        module = self.value.__module__
        if module == builtins.__name__:
            return self.value.__name__, set()
        else:
            return "%s.%s" % (module, self.value.__qualname__), {"import %s" % module}

def _check_ignored_options(self, **kwargs):
    warnings = []

    if self.has_null_arg:
        warnings.append(
            checks.Warning(
                'null has no effect on ManyToManyField.',
                obj=self,
                id='fields.W340',
            )
        )

    if self._validators:
        warnings.append(
            checks.Warning(
                'ManyToManyField does not support validators.',
                obj=self,
                id='fields.W341',
            )
        )
    if (self.remote_field.limit_choices_to and self.remote_field.through and
            not self.remote_field.through._meta.auto_created):
        warnings.append(
            checks.Warning(
                'limit_choices_to has no effect on ManyToManyField '
                'with a through model.',
                obj=self,
                id='fields.W343',
            )
        )

    return warnings

def id_for_label(self, id_):
    if id_:
        id_ += '_0'
    return id_

def json_script(value, element_id=None):
    """
    Output value JSON-encoded, wrapped in a <script type="application/json">
    tag (with an optional id).
    """
    return _json_script(value, element_id)

class BaseRenderer:
    # RemovedInDjango50Warning: When the deprecation ends, replace with
    # form_template_name = "django/forms/div.html"
    # formset_template_name = "django/forms/formsets/div.html"
    form_template_name = "django/forms/default.html"
    formset_template_name = "django/forms/formsets/default.html"

    def get_template(self, template_name):
        raise NotImplementedError("subclasses must implement get_template()")

    def render(self, template_name, context, request=None):
        template = self.get_template(template_name)
        return template.render(context, request=request).strip()

def management_form(self):
    """Return the ManagementForm instance for this FormSet."""
    if self.is_bound:
        form = ManagementForm(
            self.data,
            auto_id=self.auto_id,
            prefix=self.prefix,
            renderer=self.renderer,
        )
        form.full_clean()
    else:
        form = ManagementForm(
            auto_id=self.auto_id,
            prefix=self.prefix,
            initial={
                TOTAL_FORM_COUNT: self.total_form_count(),
                INITIAL_FORM_COUNT: self.initial_form_count(),
                MIN_NUM_FORM_COUNT: self.min_num,
                MAX_NUM_FORM_COUNT: self.max_num,
            },
            renderer=self.renderer,
        )
    return form

def get_context(self):
    fields = []
    hidden_fields = []
    top_errors = self.non_field_errors().copy()
    for name, bf in self._bound_items():
        bf_errors = self.error_class(bf.errors, renderer=self.renderer)
        if bf.is_hidden:
            if bf_errors:
                top_errors += [
                    _("(Hidden field %(name)s) %(error)s")
                    % {"name": name, "error": str(e)}
                    for e in bf_errors
                ]
            hidden_fields.append(bf)
        else:
            errors_str = str(bf_errors)
            # RemovedInDjango50Warning.
            if not isinstance(errors_str, SafeString):
                warnings.warn(
                    f"Returning a plain string from "
                    f"{self.error_class.__name__} is deprecated. Please "
                    f"customize via the template system instead.",
                    RemovedInDjango50Warning,
                )
                errors_str = mark_safe(errors_str)
            fields.append((bf, errors_str))
    return {
        "form": self,
        "fields": fields,
        "hidden_fields": hidden_fields,
        "errors": top_errors,
    }

def render(self, template_name=None, context=None, renderer=None):
    renderer = renderer or self.renderer
    template = template_name or self.template_name
    context = context or self.get_context()
    if (
        template == "django/forms/default.html"
        or template == "django/forms/formsets/default.html"
    ):
        warnings.warn(
            DEFAULT_TEMPLATE_DEPRECATION_MSG, RemovedInDjango50Warning, stacklevel=2
        )
    return mark_safe(renderer.render(template, context))

def join(value, arg, autoescape=True):
    """Join a list with a string, like Python's ``str.join(list)``."""
    try:
        if autoescape:
            value = [conditional_escape(v) for v in value]
        data = conditional_escape(arg).join(value)
    except TypeError:  # Fail silently if arg isn't iterable.
        return value
    return mark_safe(data)

def as_sql(self, compiler, connection):
    # Some backends (e.g. Oracle) raise an error when a subquery contains
    # unnecessary ORDER BY clause.
    if (
        self.subquery and
        not connection.features.ignores_unnecessary_order_by_in_subqueries
    ):
        self.clear_ordering(force=False)
    sql, params = self.get_compiler(connection=connection).as_sql()
    if self.subquery:
        sql = '(%s)' % sql
    return sql, params

def inverse(self, value):
    if not self.scaled():
        raise ValueError("Not invertible until both vmin and vmax are set")
    (vmin,), _ = self.process_value(self.vmin)
    (vmax,), _ = self.process_value(self.vmax)

    if np.iterable(value):
        val = np.ma.asarray(value)
        return vmin + val * (vmax - vmin)
    else:
        return vmin + value * (vmax - vmin)

def to_native_string(string, encoding='ascii'):
    """
    Given a string object, regardless of type, returns a representation of that
    string in the native string type, encoding and decoding where necessary.
    This assumes ASCII unless told otherwise.
    """
    out = None

    if isinstance(string, builtin_str):
        out = string
    else:
        if is_py2:
            out = string.encode(encoding)
        else:
            out = string.decode(encoding)

    return out

def prepare_method(self, method):
    """Prepares the given HTTP method."""
    self.method = method
    if self.method is not None:
        self.method = self.method.upper()

def deep_align(
    objects,
    join="inner",
    copy=True,
    indexes=None,
    exclude=frozenset(),
    raise_on_invalid=True,
    fill_value=dtypes.NA,
):
    """Align objects for merging, recursing into dictionary values.

    This function is not public API.
    """
    from .dataarray import DataArray
    from .dataset import Dataset

    if indexes is None:
        indexes = {}

    def is_alignable(obj):
        return isinstance(obj, (DataArray, Dataset))

    positions = []
    keys = []
    out = []
    targets = []
    no_key = object()
    not_replaced = object()
    for position, variables in enumerate(objects):
        if is_alignable(variables):
            positions.append(position)
            keys.append(no_key)
            targets.append(variables)
            out.append(not_replaced)
        elif is_dict_like(variables):
            current_out = {}
            for k, v in variables.items():
                if is_alignable(v) and k not in indexes:
                    # Skip variables in indexes for alignment, because these
                    # should to be overwritten instead:
                    # https://github.com/pydata/xarray/issues/725
                    # https://github.com/pydata/xarray/issues/3377
                    # TODO(shoyer): doing this here feels super-hacky -- can we
                    # move it explicitly into merge instead?
                    positions.append(position)
                    keys.append(k)
                    targets.append(v)
                    current_out[k] = not_replaced
                else:
                    current_out[k] = v
            out.append(current_out)
        elif raise_on_invalid:
            raise ValueError(
                "object to align is neither an xarray.Dataset, "
                "an xarray.DataArray nor a dictionary: {!r}".format(variables)
            )
        else:
            out.append(variables)

    aligned = align(
        *targets,
        join=join,
        copy=copy,
        indexes=indexes,
        exclude=exclude,
        fill_value=fill_value
    )

    for position, key, aligned_obj in zip(positions, keys, aligned):
        if key is no_key:
            out[position] = aligned_obj
        else:
            out[position][key] = aligned_obj

    # something went wrong: we should have replaced all sentinel values
    for arg in out:
        assert arg is not not_replaced
        if is_dict_like(arg):
            assert all(value is not not_replaced for value in arg.values())

    return out

def run_pylint(argv: Sequence[str] | None = None) -> None:
    """Run pylint.

    argv can be a sequence of strings normally supplied as arguments on the command line
    """
    from pylint.lint import Run as PylintRun

    try:
        PylintRun(argv or sys.argv[1:])
    except KeyboardInterrupt:
        sys.exit(1)

class _UnrecognizedOptionError(Exception):
    """Raised if an ArgumentManager instance tries to parse an option that is unknown."""

    def __init__(self, options: list[str], *args: object) -> None:
        self.options = options
        super().__init__(*args)

def _importtestmodule(self):
    # We assume we are only called once per module.
    importmode = self.config.getoption("--import-mode")
    try:
        mod = import_path(self.path, mode=importmode, root=self.config.rootpath)
    except SyntaxError as e:
        raise self.CollectError(
            ExceptionInfo.from_current().getrepr(style="short")
        ) from e
    except ImportPathMismatchError as e:
        raise self.CollectError(
            "import file mismatch:\n"
            "imported module %r has this __file__ attribute:\n"
            "  %s\n"
            "which is not the same as the test file we want to collect:\n"
            "  %s\n"
            "HINT: remove __pycache__ / .pyc files and/or use a "
            "unique basename for your test file modules" % e.args
        ) from e
    except ImportError as e:
        exc_info = ExceptionInfo.from_current()
        if self.config.getoption("verbose") < 2:
            exc_info.traceback = exc_info.traceback.filter(filter_traceback)
        exc_repr = (
            exc_info.getrepr(style="short")
            if exc_info.traceback
            else exc_info.exconly()
        )
        formatted_tb = str(exc_repr)
        raise self.CollectError(
            "ImportError while importing test module '{path}'.\n"
            "Hint: make sure your test modules/packages have valid Python names.\n"
            "Traceback:\n"
            "{traceback}".format(path=self.path, traceback=formatted_tb)
        ) from e
    except skip.Exception as e:
        if e.allow_module_level:
            raise
        raise self.CollectError(
            "Using pytest.skip outside of a test will skip the entire module. "
            "If that's your intention, pass `allow_module_level=True`. "
            "If you want to skip a specific test or an entire class, "
            "use the @pytest.mark.skip or @pytest.mark.skipif decorators."
        ) from e
    self.config.pluginmanager.consider_module(mod)
    return mod

def get_user() -> Optional[str]:
    """Return the current user name, or None if getuser() does not work
    in the current environment (see #1010)."""
    import getpass

    try:
        return getpass.getuser()
    except (ImportError, KeyError):
        return None

def _fit(self, X):
    self._check_algorithm_metric()
    if self.metric_params is None:
        self.effective_metric_params_ = {}
    else:
        self.effective_metric_params_ = self.metric_params.copy()

    effective_p = self.effective_metric_params_.get('p', self.p)
    if self.metric in ['wminkowski', 'minkowski']:
        self.effective_metric_params_['p'] = effective_p

    self.effective_metric_ = self.metric
    # For minkowski distance, use more efficient methods where available
    if self.metric == 'minkowski':
        p = self.effective_metric_params_.pop('p', 2)
        if p < 1:
            raise ValueError("p must be greater than one "
                             "for minkowski metric")
        elif p == 1:
            self.effective_metric_ = 'manhattan'
        elif p == 2:
            self.effective_metric_ = 'euclidean'
        elif p == np.inf:
            self.effective_metric_ = 'chebyshev'
        else:
            self.effective_metric_params_['p'] = p

    if isinstance(X, NeighborsBase):
        self._fit_X = X._fit_X
        self._tree = X._tree
        self._fit_method = X._fit_method
        return self

    elif isinstance(X, BallTree):
        self._fit_X = X.data
        self._tree = X
        self._fit_method = 'ball_tree'
        return self

    elif isinstance(X, KDTree):
        self._fit_X = X.data
        self._tree = X
        self._fit_method = 'kd_tree'
        return self

    X = check_array(X, accept_sparse='csr')

    n_samples = X.shape[0]
    if n_samples == 0:
        raise ValueError("n_samples must be greater than 0")

    if issparse(X):
        if self.algorithm not in ('auto', 'brute'):
            warnings.warn("cannot use tree with sparse input: "
                          "using brute force")
        if self.effective_metric_ not in VALID_METRICS_SPARSE['brute'] \
                and not callable(self.effective_metric_):

            raise ValueError("metric '%s' not valid for sparse input"
                             % self.effective_metric_)
        self._fit_X = X.copy()
        self._tree = None
        self._fit_method = 'brute'
        return self

    self._fit_method = self.algorithm
    self._fit_X = X

    if self._fit_method == 'auto':
        # A tree approach is better for small number of neighbors,
        # and KDTree is generally faster when available
        if ((self.n_neighbors is None or
             self.n_neighbors < self._fit_X.shape[0] // 2) and
                self.metric != 'precomputed'):
            if self.effective_metric_ in VALID_METRICS['kd_tree']:
                self._fit_method = 'kd_tree'
            elif (callable(self.effective_metric_) or
                    self.effective_metric_ in VALID_METRICS['ball_tree']):
                self._fit_method = 'ball_tree'
            else:
                self._fit_method = 'brute'
        else:
            self._fit_method = 'brute'

    if self._fit_method == 'ball_tree':
        self._tree = BallTree(X, self.leaf_size,
                              metric=self.effective_metric_,
                              **self.effective_metric_params_)
    elif self._fit_method == 'kd_tree':
        self._tree = KDTree(X, self.leaf_size,
                            metric=self.effective_metric_,
                            **self.effective_metric_params_)
    elif self._fit_method == 'brute':
        self._tree = None
    else:
        raise ValueError("algorithm = '%s' not recognized"
                         % self.algorithm)

    if self.n_neighbors is not None:
        if self.n_neighbors <= 0:
            raise ValueError(
                "Expected n_neighbors > 0. Got %d" %
                self.n_neighbors
            )

    return self

def _check_algorithm_metric(self):
    if self.algorithm not in ['auto', 'brute',
                              'kd_tree', 'ball_tree']:
        raise ValueError("unrecognized algorithm: '%s'" % self.algorithm)

    if self.algorithm == 'auto':
        if self.metric == 'precomputed':
            alg_check = 'brute'
        elif (callable(self.metric) or
              self.metric in VALID_METRICS['ball_tree']):
            alg_check = 'ball_tree'
        else:
            alg_check = 'brute'
    else:
        alg_check = self.algorithm

    if callable(self.metric):
        if self.algorithm == 'kd_tree':
            # callable metric is only valid for brute force and ball_tree
            raise ValueError(
                "kd_tree algorithm does not support callable metric '%s'"
                % self.metric)
    elif self.metric not in VALID_METRICS[alg_check]:
        raise ValueError("Metric '%s' not valid for algorithm '%s'"
                         % (self.metric, self.algorithm))

    if self.metric_params is not None and 'p' in self.metric_params:
        warnings.warn("Parameter p is found in metric_params. "
                      "The corresponding parameter from __init__ "
                      "is ignored.", SyntaxWarning, stacklevel=3)
        effective_p = self.metric_params['p']
    else:
        effective_p = self.p

    if self.metric in ['wminkowski', 'minkowski'] and effective_p < 1:
        raise ValueError("p must be greater than one for minkowski metric")

def parse_item_name(text: str) -> Tuple[str, str]:
    """Match ':role:`name`' or 'name'"""
    m = self._name_rgx.match(text)
    if m:
        g = m.groups()
        if g[1] is None:
            return g[3], None
        else:
            return g[2], g[1]
    raise ValueError("%s is not a item name" % text)

def _format_field(self, _name: str, _type: str, _desc: List[str]) -> List[str]:
    _desc = self._strip_empty(_desc)
    has_desc = any(_desc)
    separator = ' -- ' if has_desc else ''
    if _name:
        if _type:
            if '`' in _type:
                field = '**%s** (%s)%s' % (_name, _type, separator)
            else:
                field = '**%s** (*%s*)%s' % (_name, _type, separator)
        else:
            field = '**%s**%s' % (_name, separator)
    elif _type:
        if '`' in _type:
            field = '%s%s' % (_type, separator)
        else:
            field = '*%s*%s' % (_type, separator)
    else:
        field = ''

    if has_desc:
        _desc = self._fix_field_desc(_desc)
        if _desc[0]:
            return [field + _desc[0]] + _desc[1:]
        else:
            return [field] + _desc
    else:
        return [field]

def _escape_args_and_kwargs(self, name: str) -> str:
    if name.endswith('_'):
        name = name[:-1] + r'\_'

    if name[:2] == '**':
        return r'\*\*' + name[2:]
    elif name[:1] == '*':
        return r'\*' + name[1:]
    else:
        return name

def add_entry(word: str, subword: str, main: str, link: bool = True,
              dic: Dict = new, key: str = None) -> None:
    # Force the word to be unicode if it's a ASCII bytestring.
    # This will solve problems with unicode normalization later.
    # For instance the RFC role will add bytestrings at the moment
    word = str(word)
    entry = dic.get(word)
    if not entry:
        dic[word] = entry = [[], {}, key]
    if subword:
        add_entry(subword, '', main, link=link, dic=entry[1], key=key)
    elif link:
        try:
            uri = builder.get_relative_uri('genindex', fn) + '#' + tid
        except NoUri:
            pass
        else:
            entry[0].append((main, uri))

def write_genindex(self) -> None:
    # the total count of lines for each index letter, used to distribute
    # the entries into two columns
    genindex = IndexEntries(self.env).create_index(self)
    indexcounts = []
    for _k, entries in genindex:
        indexcounts.append(sum(1 + len(subitems)
                               for _, (_, subitems, _) in entries))

    genindexcontext = {
        'genindexentries': genindex,
        'genindexcounts': indexcounts,
        'split_index': self.config.html_split_index,
    }
    logger.info(' genindex', nonl=True)

    if self.config.html_split_index:
        self.handle_page('genindex', genindexcontext,
                         'genindex-split.html')
        self.handle_page('genindex-all', genindexcontext,
                         'genindex.html')
        for (key, entries), count in zip(genindex, indexcounts):
            ctx = {'key': key, 'entries': entries, 'count': count,
                   'genindexentries': genindex}
            self.handle_page('genindex-' + key, ctx,
                             'genindex-single.html')
    else:
        self.handle_page('genindex', genindexcontext, 'genindex.html')

def keyfunc(entry: Tuple[str, List]) -> Tuple[str, str]:
    key, (void, void, category_key) = entry
    if category_key:
        # using specified category key to sort
        key = category_key
    lckey = unicodedata.normalize('NFD', key.lower())
    if lckey.startswith('\N{RIGHT-TO-LEFT MARK}'):
        lckey = lckey[1:]
    if lckey[0:1].isalpha() or lckey.startswith('_'):
        lckey = chr(127) + lckey
    # ensure a determinstic order *within* letters by also sorting on
    # the entry itself
    return (lckey, entry[0])

def create_index(self, builder: Builder, group_entries: bool = True,
                 _fixre: Pattern = re.compile(r'(.*) ([(][^()]*[)])')
                 ) -> List[Tuple[str, List[Tuple[str, Any]]]]:
    """Create the real index from the collected index entries."""
    new = {}  # type: Dict[str, List]

    def add_entry(word: str, subword: str, main: str, link: bool = True,
                  dic: Dict = new, key: str = None) -> None:
        # Force the word to be unicode if it's a ASCII bytestring.
        # This will solve problems with unicode normalization later.
        # For instance the RFC role will add bytestrings at the moment
        word = str(word)
        entry = dic.get(word)
        if not entry:
            dic[word] = entry = [[], {}, key]
        if subword:
            add_entry(subword, '', main, link=link, dic=entry[1], key=key)
        elif link:
            try:
                uri = builder.get_relative_uri('genindex', fn) + '#' + tid
            except NoUri:
                pass
            else:
                entry[0].append((main, uri))

    domain = cast(IndexDomain, self.env.get_domain('index'))
    for fn, entries in domain.entries.items():
        # new entry types must be listed in directives/other.py!
        for type, value, tid, main, index_key in entries:
            try:
                if type == 'single':
                    try:
                        entry, subentry = split_into(2, 'single', value)
                    except ValueError:
                        entry, = split_into(1, 'single', value)
                        subentry = ''
                    add_entry(entry, subentry, main, key=index_key)
                elif type == 'pair':
                    first, second = split_into(2, 'pair', value)
                    add_entry(first, second, main, key=index_key)
                    add_entry(second, first, main, key=index_key)
                elif type == 'triple':
                    first, second, third = split_into(3, 'triple', value)
                    add_entry(first, second + ' ' + third, main, key=index_key)
                    add_entry(second, third + ', ' + first, main, key=index_key)
                    add_entry(third, first + ' ' + second, main, key=index_key)
                elif type == 'see':
                    first, second = split_into(2, 'see', value)
                    add_entry(first, _('see %s') % second, None,
                              link=False, key=index_key)
                elif type == 'seealso':
                    first, second = split_into(2, 'see', value)
                    add_entry(first, _('see also %s') % second, None,
                              link=False, key=index_key)
                else:
                    logger.warning(__('unknown index entry type %r'), type, location=fn)
            except ValueError as err:
                logger.warning(str(err), location=fn)

    # sort the index entries for same keyword.
    def keyfunc0(entry: Tuple[str, str]) -> Tuple[bool, str]:
        main, uri = entry
        return (not main, uri)  # show main entries at first

    for indexentry in new.values():
        indexentry[0].sort(key=keyfunc0)
        for subentry in indexentry[1].values():
            subentry[0].sort(key=keyfunc0)  # type: ignore

    # sort the index entries; put all symbols at the front, even those
    # following the letters in ASCII, this is where the chr(127) comes from
    def keyfunc(entry: Tuple[str, List]) -> Tuple[str, str]:
        key, (void, void, category_key) = entry
        if category_key:
            # using specified category key to sort
            key = category_key
        lckey = unicodedata.normalize('NFD', key.lower())
        if lckey.startswith('\N{RIGHT-TO-LEFT MARK}'):
            lckey = lckey[1:]
        if lckey[0:1].isalpha() or lckey.startswith('_'):
            lckey = chr(127) + lckey
        # ensure a determinstic order *within* letters by also sorting on
        # the entry itself
        return (lckey, entry[0])
    newlist = sorted(new.items(), key=keyfunc)

    if group_entries:
        # fixup entries: transform
        #   func() (in module foo)
        #   func() (in module bar)
        # into
        #   func()
        #     (in module foo)
        #     (in module bar)
        oldkey = ''
        oldsubitems = None  # type: Dict[str, List]
        i = 0
        while i < len(newlist):
            key, (targets, subitems, _key) = newlist[i]
            # cannot move if it has subitems; structure gets too complex
            if not subitems:
                m = _fixre.match(key)
                if m:
                    if oldkey == m.group(1):
                        # prefixes match: add entry as subitem of the
                        # previous entry
                        oldsubitems.setdefault(m.group(2), [[], {}, _key])[0].\
                            extend(targets)
                        del newlist[i]
                        continue
                    oldkey = m.group(1)
                else:
                    oldkey = key
            oldsubitems = subitems
            i += 1

    # sort the sub-index entries
    def keyfunc2(entry: Tuple[str, List]) -> str:
        key = unicodedata.normalize('NFD', entry[0].lower())
        if key.startswith('\N{RIGHT-TO-LEFT MARK}'):
            key = key[1:]
        if key[0:1].isalpha() or key.startswith('_'):
            key = chr(127) + key
        return key

    # group the entries by letter
    def keyfunc3(item: Tuple[str, List]) -> str:
        # hack: mutating the subitems dicts to a list in the keyfunc
        k, v = item
        v[1] = sorted(((si, se) for (si, (se, void, void)) in v[1].items()),
                      key=keyfunc2)
        if v[2] is None:
            # now calculate the key
            if k.startswith('\N{RIGHT-TO-LEFT MARK}'):
                k = k[1:]
            letter = unicodedata.normalize('NFD', k[0])[0].upper()
            if letter.isalpha() or letter == '_':
                return letter
            else:
                # get all other symbols under one heading
                return _('Symbols')
        else:
            return v[2]
    return [(key_, list(group))
            for (key_, group) in groupby(newlist, keyfunc3)]

def type_to_xref(text: str, env: BuildEnvironment = None) -> addnodes.pending_xref:
    """Convert a type string to a cross reference node."""
    if text == 'None':
        reftype = 'obj'
    else:
        reftype = 'class'

    if env:
        kwargs = {'py:module': env.ref_context.get('py:module'),
                  'py:class': env.ref_context.get('py:class')}
    else:
        kwargs = {}

    return pending_xref('', nodes.Text(text),
                        refdomain='py', reftype=reftype, reftarget=text, **kwargs)

def stringify(annotation: Any) -> str:
    """Stringify type annotation object."""
    from sphinx.util import inspect  # lazy loading

    if isinstance(annotation, str):
        if annotation.startswith("'") and annotation.endswith("'"):
            # might be a double Forward-ref'ed type.  Go unquoting.
            return annotation[1:-1]
        else:
            return annotation
    elif isinstance(annotation, TypeVar):
        return annotation.__name__
    elif inspect.isNewType(annotation):
        # Could not get the module where it defiend
        return annotation.__name__
    elif not annotation:
        return repr(annotation)
    elif annotation is NoneType:
        return 'None'
    elif (getattr(annotation, '__module__', None) == 'builtins' and
          hasattr(annotation, '__qualname__')):
        return annotation.__qualname__
    elif annotation is Ellipsis:
        return '...'

    if sys.version_info >= (3, 7):  # py37+
        return _stringify_py37(annotation)
    else:
        return _stringify_py36(annotation)

def _stringify_py37(annotation: Any) -> str:
    """stringify() for py37+."""
    module = getattr(annotation, '__module__', None)
    if module == 'typing':
        if getattr(annotation, '_name', None):
            qualname = annotation._name
        elif getattr(annotation, '__qualname__', None):
            qualname = annotation.__qualname__
        elif getattr(annotation, '__forward_arg__', None):
            qualname = annotation.__forward_arg__
        else:
            qualname = stringify(annotation.__origin__)  # ex. Union
    elif hasattr(annotation, '__qualname__'):
        qualname = '%s.%s' % (module, annotation.__qualname__)
    elif hasattr(annotation, '__origin__'):
        # instantiated generic provided by a user
        qualname = stringify(annotation.__origin__)
    else:
        # we weren't able to extract the base type, appending arguments would
        # only make them appear twice
        return repr(annotation)

    if getattr(annotation, '__args__', None):
        if not isinstance(annotation.__args__, (list, tuple)):
            # broken __args__ found
            pass
        elif qualname == 'Union':
            if len(annotation.__args__) > 1 and annotation.__args__[-1] is NoneType:
                if len(annotation.__args__) > 2:
                    args = ', '.join(stringify(a) for a in annotation.__args__[:-1])
                    return 'Optional[Union[%s]]' % args
                else:
                    return 'Optional[%s]' % stringify(annotation.__args__[0])
            else:
                args = ', '.join(stringify(a) for a in annotation.__args__)
                return 'Union[%s]' % args
        elif qualname == 'Callable':
            args = ', '.join(stringify(a) for a in annotation.__args__[:-1])
            returns = stringify(annotation.__args__[-1])
            return '%s[[%s], %s]' % (qualname, args, returns)
        elif str(annotation).startswith('typing.Annotated'):  # for py39+
            return stringify(annotation.__args__[0])
        elif all(is_system_TypeVar(a) for a in annotation.__args__):
            # Suppress arguments if all system defined TypeVars (ex. Dict[KT, VT])
            return qualname
        else:
            args = ', '.join(stringify(a) for a in annotation.__args__)
            return '%s[%s]' % (qualname, args)

    return qualname

def record_typehints(app: Sphinx, objtype: str, name: str, obj: Any,
                     options: Dict, args: str, retann: str) -> None:
    """Record type hints to env object."""
    try:
        if callable(obj):
            annotations = app.env.temp_data.setdefault('annotations', {})
            annotation = annotations.setdefault(name, OrderedDict())
            sig = inspect.signature(obj, type_aliases=app.config.autodoc_type_aliases)
            for param in sig.parameters.values():
                if param.annotation is not param.empty:
                    annotation[param.name] = typing.stringify(param.annotation)
            if sig.return_annotation is not sig.empty:
                annotation['return'] = typing.stringify(sig.return_annotation)
    except (TypeError, ValueError):
        pass

def restify(cls: Optional["Type"]) -> str:
    """Convert python class to a reST reference."""
    from sphinx.util import inspect  # lazy loading

    if cls is None or cls is NoneType:
        return ':obj:`None`'
    elif cls is Ellipsis:
        return '...'
    elif inspect.isNewType(cls):
        return ':class:`%s`' % cls.__name__
    elif cls.__module__ in ('__builtin__', 'builtins'):
        return ':class:`%s`' % cls.__name__
    else:
        if sys.version_info >= (3, 7):  # py37+
            return _restify_py37(cls)
        else:
            return _restify_py36(cls)

def _parse_annotation(annotation: str, env: BuildEnvironment = None) -> List[Node]:
    """Parse type annotation."""
    def unparse(node: ast.AST) -> List[Node]:
        if isinstance(node, ast.Attribute):
            return [nodes.Text("%s.%s" % (unparse(node.value)[0], node.attr))]
        elif isinstance(node, ast.Expr):
            return unparse(node.value)
        elif isinstance(node, ast.Index):
            return unparse(node.value)
        elif isinstance(node, ast.List):
            result = [addnodes.desc_sig_punctuation('', '[')]  # type: List[Node]
            for elem in node.elts:
                result.extend(unparse(elem))
                result.append(addnodes.desc_sig_punctuation('', ', '))
            result.pop()
            result.append(addnodes.desc_sig_punctuation('', ']'))
            return result
        elif isinstance(node, ast.Module):
            return sum((unparse(e) for e in node.body), [])
        elif isinstance(node, ast.Name):
            return [nodes.Text(node.id)]
        elif isinstance(node, ast.Subscript):
            result = unparse(node.value)
            result.append(addnodes.desc_sig_punctuation('', '['))
            result.extend(unparse(node.slice))
            result.append(addnodes.desc_sig_punctuation('', ']'))
            return result
        elif isinstance(node, ast.Tuple):
            if node.elts:
                result = []
                for elem in node.elts:
                    result.extend(unparse(elem))
                    result.append(addnodes.desc_sig_punctuation('', ', '))
                result.pop()
            else:
                result = [addnodes.desc_sig_punctuation('', '('),
                          addnodes.desc_sig_punctuation('', ')')]

            return result
        else:
            if sys.version_info >= (3, 6):
                if isinstance(node, ast.Constant):
                    if node.value is Ellipsis:
                        return [addnodes.desc_sig_punctuation('', "...")]
                    else:
                        return [nodes.Text(node.value)]

            if sys.version_info < (3, 8):
                if isinstance(node, ast.Ellipsis):
                    return [addnodes.desc_sig_punctuation('', "...")]
                elif isinstance(node, ast.NameConstant):
                    return [nodes.Text(node.value)]

            raise SyntaxError  # unsupported syntax

    if env is None:
        warnings.warn("The env parameter for _parse_annotation becomes required now.",
                      RemovedInSphinx50Warning, stacklevel=2)

    try:
        tree = ast_parse(annotation)
        result = unparse(tree)
        for i, node in enumerate(result):
            if isinstance(node, nodes.Text):
                result[i] = type_to_xref(str(node), env)
        return result
    except SyntaxError:
        return [type_to_xref(annotation, env)]

def _stringify_py37(annotation: Any) -> str:
    """stringify() for py37+."""
    module = getattr(annotation, '__module__', None)
    if module == 'typing':
        if getattr(annotation, '_name', None):
            qualname = annotation._name
        elif getattr(annotation, '__qualname__', None):
            qualname = annotation.__qualname__
        elif getattr(annotation, '__forward_arg__', None):
            qualname = annotation.__forward_arg__
        else:
            qualname = stringify(annotation.__origin__)  # ex. Union
    elif hasattr(annotation, '__qualname__'):
        qualname = '%s.%s' % (module, annotation.__qualname__)
    elif hasattr(annotation, '__origin__'):
        # instantiated generic provided by a user
        qualname = stringify(annotation.__origin__)
    else:
        # we weren't able to extract the base type, appending arguments would
        # only make them appear twice
        return repr(annotation)

    if getattr(annotation, '__args__', None):
        if not isinstance(annotation.__args__, (list, tuple)):
            # broken __args__ found
            pass
        elif qualname == 'Union':
            if len(annotation.__args__) > 1 and annotation.__args__[-1] is NoneType:
                if len(annotation.__args__) > 2:
                    args = ', '.join(stringify(a) for a in annotation.__args__[:-1])
                    return 'Optional[Union[%s]]' % args
                else:
                    return 'Optional[%s]' % stringify(annotation.__args__[0])
            else:
                args = ', '.join(stringify(a) for a in annotation.__args__)
                return 'Union[%s]' % args
        elif qualname == 'Callable':
            args = ', '.join(stringify(a) for a in annotation.__args__[:-1])
            returns = stringify(annotation.__args__[-1])
            return '%s[[%s], %s]' % (qualname, args, returns)
        elif str(annotation).startswith('typing.Annotated'):  # for py39+
            return stringify(annotation.__args__[0])
        elif all(is_system_TypeVar(a) for a in annotation.__args__):
            # Suppress arguments if all system defined TypeVars (ex. Dict[KT, VT])
            return qualname
        else:
            args = ', '.join(stringify(a) for a in annotation.__args__)
            return '%s[%s]' % (qualname, args)

    return qualname

def eval(cls, p, q):
    from sympy.core.add import Add
    from sympy.core.mul import Mul
    from sympy.core.singleton import S
    from sympy.core.exprtools import gcd_terms
    from sympy.polys.polytools import gcd

    def doit(p, q):
        """Try to return p % q if both are numbers or +/-p is known
        to be less than or equal q.
        """

        if p.is_infinite or q.is_infinite or p is nan or q is nan:
            return nan
        if (p == q or p == -q or
                p.is_Pow and p.exp.is_Integer and p.base == q or
                p.is_integer and q == 1):
            return S.Zero

        if q.is_Number:
            if p.is_Number:
                return (p % q)
            if q == 2:
                if p.is_even:
                    return S.Zero
                elif p.is_odd:
                    return S.One

        # by ratio
        r = p/q
        try:
            d = int(r)
        except TypeError:
            pass
        else:
            if type(d) is int:
                rv = p - d*q
                if (rv*q < 0) == True:
                    rv += q
                return rv

        # by difference
        d = p - q
        if d.is_negative:
            if q.is_negative:
                return d
            elif q.is_positive:
                return p

    rv = doit(p, q)
    if rv is not None:
        return rv

    # denest
    if p.func is cls:
        # easy
        qinner = p.args[1]
        if qinner == q:
            return p
        # XXX other possibilities?

    # extract gcd; any further simplification should be done by the user
    G = gcd(p, q)
    if G != 1:
        p, q = [
            gcd_terms(i/G, clear=False, fraction=False) for i in (p, q)]
    pwas, qwas = p, q

    # simplify terms
    # (x + y + 2) % x -> Mod(y + 2, x)
    if p.is_Add:
        args = []
        for i in p.args:
            a = cls(i, q)
            if a.count(cls) > i.count(cls):
                args.append(i)
            else:
                args.append(a)
        if args != list(p.args):
            p = Add(*args)

    else:
        # handle coefficients if they are not Rational
        # since those are not handled by factor_terms
        # e.g. Mod(.6*x, .3*y) -> 0.3*Mod(2*x, y)
        cp, p = p.as_coeff_Mul()
        cq, q = q.as_coeff_Mul()
        ok = False
        if not cp.is_Rational or not cq.is_Rational:
            r = cp % cq
            if r == 0:
                G *= cq
                p *= int(cp/cq)
                ok = True
        if not ok:
            p = cp*p
            q = cq*q

    # simple -1 extraction
    if p.could_extract_minus_sign() and q.could_extract_minus_sign():
        G, p, q = [-i for i in (G, p, q)]

    # check again to see if p and q can now be handled as numbers
    rv = doit(p, q)
    if rv is not None:
        return rv*G

    # put 1.0 from G on inside
    if G.is_Float and G == 1:
        p *= G
        return cls(p, q, evaluate=False)
    elif G.is_Mul and G.args[0].is_Float and G.args[0] == 1:
        p = G.args[0]*p
        G = Mul._from_args(G.args[1:])
    return G*cls(p, q, evaluate=(p, q) != (pwas, qwas))

def _print_BasisDependent(self, expr):
    from sympy.vector import Vector

    if not self._use_unicode:
        raise NotImplementedError("ASCII pretty printing of BasisDependent is not implemented")

    if expr == expr.zero:
        return prettyForm(expr.zero._pretty_form)
    o1 = []
    vectstrs = []
    if isinstance(expr, Vector):
        items = expr.separate().items()
    else:
        items = [(0, expr)]
    for system, vect in items:
        inneritems = list(vect.components.items())
        inneritems.sort(key = lambda x: x[0].__str__())
        for k, v in inneritems:
            #if the coef of the basis vector is 1
            #we skip the 1
            if v == 1:
                o1.append(u"" +
                          k._pretty_form)
            #Same for -1
            elif v == -1:
                o1.append(u"(-1) " +
                          k._pretty_form)
            #For a general expr
            else:
                #We always wrap the measure numbers in
                #parentheses
                arg_str = self._print(
                    v).parens()[0]

                o1.append(arg_str + ' ' + k._pretty_form)
            vectstrs.append(k._pretty_form)

    #outstr = u("").join(o1)
    if o1[0].startswith(u" + "):
        o1[0] = o1[0][3:]
    elif o1[0].startswith(" "):
        o1[0] = o1[0][1:]
    #Fixing the newlines
    lengths = []
    strs = ['']
    for i, partstr in enumerate(o1):
        # XXX: What is this hack?
        if '\n' in partstr:
            tempstr = partstr
            tempstr = tempstr.replace(vectstrs[i], '')
            tempstr = tempstr.replace(u'\N{RIGHT PARENTHESIS UPPER HOOK}',
                                      u'\N{RIGHT PARENTHESIS UPPER HOOK}'
                                      + ' ' + vectstrs[i])
            o1[i] = tempstr
    o1 = [x.split('\n') for x in o1]
    n_newlines = max([len(x) for x in o1])
    for parts in o1:
        lengths.append(len(parts[0]))
        for j in range(n_newlines):
            if j+1 <= len(parts):
                if j >= len(strs):
                    strs.append(' ' * (sum(lengths[:-1]) +
                                       3*(len(lengths)-1)))
                if j == 0:
                    strs[0] += parts[0] + ' + '
                else:
                    strs[j] += parts[j] + ' '*(lengths[-1] -
                                               len(parts[j])+
                                               3)
            else:
                if j >= len(strs):
                    strs.append(' ' * (sum(lengths[:-1]) +
                                       3*(len(lengths)-1)))
                strs[j] += ' '*(lengths[-1]+3)

    return prettyForm(u'\n'.join([s[:-3] for s in strs]))

def _print_MatAdd(self, expr):
    s = None
    for item in expr.args:
        pform = self._print(item)
        if s is None:
            s = pform     # First element
        else:
            if S(item.args[0]).is_negative:
                s = prettyForm(*stringPict.next(s, ' '))
                pform = self._print(item)
            else:
                s = prettyForm(*stringPict.next(s, ' + '))
            s = prettyForm(*stringPict.next(s, pform))

    return s

def _solve_reduced_system(system, gens, entry=False):
    """Recursively solves reduced polynomial systems. """
    if len(system) == len(gens) == 1:
        zeros = list(roots(system[0], gens[-1]).keys())
        return [(zero,) for zero in zeros]

    basis = groebner(system, gens, polys=True)

    if len(basis) == 1 and basis[0].is_ground:
        if not entry:
            return []
        else:
            return None

    univariate = list(filter(_is_univariate, basis))

    if len(univariate) == 1:
        f = univariate.pop()
    else:
        raise NotImplementedError(filldedent('''
            only zero-dimensional systems supported
            (finite number of solutions)
            '''))

    gens = f.gens
    gen = gens[-1]

    zeros = list(roots(f.ltrim(gen)).keys())

    if not zeros:
        return []

    if len(basis) == 1:
        return [(zero,) for zero in zeros]

    solutions = []

    for zero in zeros:
        new_system = []
        new_gens = gens[:-1]

        for b in basis[:-1]:
            eq = _subs_root(b, gen, zero)

            if eq is not S.Zero:
                new_system.append(eq)

        for solution in _solve_reduced_system(new_system, new_gens):
            solutions.append(solution + (zero,))

    if solutions and len(solutions[0]) != len(gens):
        raise NotImplementedError(filldedent('''
            only zero-dimensional systems supported
            (finite number of solutions)
            '''))
    return solutions

def _collect_factor_and_dimension(self, expr):
    """
    Return tuple with scale factor expression and dimension expression.
    """
    from sympy.physics.units import Quantity
    if isinstance(expr, Quantity):
        return expr.scale_factor, expr.dimension
    elif isinstance(expr, Mul):
        factor = 1
        dimension = Dimension(1)
        for arg in expr.args:
            arg_factor, arg_dim = self._collect_factor_and_dimension(arg)
            factor *= arg_factor
            dimension *= arg_dim
        return factor, dimension
    elif isinstance(expr, Pow):
        factor, dim = self._collect_factor_and_dimension(expr.base)
        exp_factor, exp_dim = self._collect_factor_and_dimension(expr.exp)
        if self.get_dimension_system().is_dimensionless(exp_dim):
            exp_dim = 1
        return factor ** exp_factor, dim ** (exp_factor * exp_dim)
    elif isinstance(expr, Add):
        factor, dim = self._collect_factor_and_dimension(expr.args[0])
        for addend in expr.args[1:]:
            addend_factor, addend_dim = \
                self._collect_factor_and_dimension(addend)
            if dim != addend_dim:
                raise ValueError(
                    'Dimension of "{}" is {}, '
                    'but it should be {}'.format(
                        addend, addend_dim, dim))
            factor += addend_factor
        return factor, dim
    elif isinstance(expr, Derivative):
        factor, dim = self._collect_factor_and_dimension(expr.args[0])
        for independent, count in expr.variable_count:
            ifactor, idim = self._collect_factor_and_dimension(independent)
            factor /= ifactor**count
            dim /= idim**count
        return factor, dim
    elif isinstance(expr, Function):
        fds = [self._collect_factor_and_dimension(arg) for arg in expr.args]
        dims = [Dimension(1) if self.get_dimension_system().is_dimensionless(d[1]) else d[1] for d in fds]
        return (expr.func(*(f[0] for f in fds)), *dims)
    elif isinstance(expr, Dimension):
        return S.One, expr
    else:
        return expr, Dimension(1)

class Dimension(Expr):
    """
    This class represent the dimension of a physical quantities.

    The ``Dimension`` constructor takes as parameters a name and an optional
    symbol.

    For example, in classical mechanics we know that time is different from
    temperature and dimensions make this difference (but they do not provide
    any measure of these quantites.

        >>> from sympy.physics.units import Dimension
        >>> length = Dimension('length')
        >>> length
        Dimension(length)
        >>> time = Dimension('time')
        >>> time
        Dimension(time)

    Dimensions can be composed using multiplication, division and
    exponentiation (by a number) to give new dimensions. Addition and
    subtraction is defined only when the two objects are the same dimension.

        >>> velocity = length / time
        >>> velocity
        Dimension(length/time)

    It is possible to use a dimension system object to get the dimensionsal
    dependencies of a dimension, for example the dimension system used by the
    SI units convention can be used:

        >>> from sympy.physics.units.systems.si import dimsys_SI
        >>> dimsys_SI.get_dimensional_dependencies(velocity)
        {Dimension(length, L): 1, Dimension(time, T): -1}
        >>> length + length
        Dimension(length)
        >>> l2 = length**2
        >>> l2
        Dimension(length**2)
        >>> dimsys_SI.get_dimensional_dependencies(l2)
        {Dimension(length, L): 2}

    """

    _op_priority = 13.0

    # XXX: This doesn't seem to be used anywhere...
    _dimensional_dependencies = {}  # type: ignore

    is_commutative = True
    is_number = False
    # make sqrt(M**2) --> M
    is_positive = True
    is_real = True

    def __new__(cls, name, symbol=None):

        if isinstance(name, str):
            name = Symbol(name)
        else:
            name = sympify(name)

        if not isinstance(name, Expr):
            raise TypeError("Dimension name needs to be a valid math expression")

        if isinstance(symbol, str):
            symbol = Symbol(symbol)
        elif symbol is not None:
            assert isinstance(symbol, Symbol)

        obj = Expr.__new__(cls, name)

        obj._name = name
        obj._symbol = symbol
        return obj

    @property
    def name(self):
        return self._name

    @property
    def symbol(self):
        return self._symbol

    def __str__(self):
        """
        Display the string representation of the dimension.
        """
        if self.symbol is None:
            return "Dimension(%s)" % (self.name)
        else:
            return "Dimension(%s, %s)" % (self.name, self.symbol)

    def __repr__(self):
        return self.__str__()

    def __neg__(self):
        return self

    def __add__(self, other):
        from sympy.physics.units.quantities import Quantity
        other = sympify(other)
        if isinstance(other, Basic):
            if other.has(Quantity):
                raise TypeError("cannot sum dimension and quantity")
            if isinstance(other, Dimension) and self == other:
                return self
            return super().__add__(other)
        return self

    def __radd__(self, other):
        return self.__add__(other)

    def __sub__(self, other):
        # there is no notion of ordering (or magnitude) among dimension,
        # subtraction is equivalent to addition when the operation is legal
        return self + other

    def __rsub__(self, other):
        # there is no notion of ordering (or magnitude) among dimension,
        # subtraction is equivalent to addition when the operation is legal
        return self + other

    def __pow__(self, other):
        return self._eval_power(other)

    def _eval_power(self, other):
        other = sympify(other)
        return Dimension(self.name**other)

    def __mul__(self, other):
        from sympy.physics.units.quantities import Quantity
        if isinstance(other, Basic):
            if other.has(Quantity):
                raise TypeError("cannot sum dimension and quantity")
            if isinstance(other, Dimension):
                return Dimension(self.name*other.name)
            if not other.free_symbols:  # other.is_number cannot be used
                return self
            return super().__mul__(other)
        return self

    def __rmul__(self, other):
        return self.__mul__(other)

    def __truediv__(self, other):
        return self*Pow(other, -1)

    def __rtruediv__(self, other):
        return other * pow(self, -1)

    @classmethod
    def _from_dimensional_dependencies(cls, dependencies):
        return reduce(lambda x, y: x * y, (
            d**e for d, e in dependencies.items()
        ), 1)

    def has_integer_powers(self, dim_sys):
        """
        Check if the dimension object has only integer powers.

        All the dimension powers should be integers, but rational powers may
        appear in intermediate steps. This method may be used to check that the
        final result is well-defined.
        """

        return all(dpow.is_Integer for dpow in dim_sys.get_dimensional_dependencies(self).values())

def __mul__(self, other):
    from sympy.physics.units import Quantity
    if not isinstance(other, (Quantity, Prefix)):
        return super().__mul__(other)

    fact = self.scale_factor * other.scale_factor

    if fact == 1:
        return 1
    elif isinstance(other, Prefix):
        # simplify prefix
        for p in PREFIXES:
            if PREFIXES[p].scale_factor == fact:
                return PREFIXES[p]
        return fact

    return self.scale_factor * other

def get_quantity_scale_factor(self, unit):
    qsfm = self.get_dimension_system()._quantity_scale_factors
    if unit in qsfm:
        return qsfm[unit]
    return super().get_quantity_scale_factor(unit)

def _update(self, event):
    """Update the slider position."""
    if self.ignore(event) or event.button != 1:
        return

    if event.name == 'button_press_event' and event.inaxes == self.ax:
        self.drag_active = True
        event.canvas.grab_mouse(self.ax)

    if not self.drag_active:
        return

    elif ((event.name == 'button_release_event') or
          (event.name == 'button_press_event' and
           event.inaxes != self.ax)):
        self.drag_active = False
        event.canvas.release_mouse(self.ax)
        return
    if self.orientation == 'vertical':
        val = self._value_in_bounds(event.ydata)
    else:
        val = self._value_in_bounds(event.xdata)
    if val not in [None, self.val]:
        self.set_val(val)

def _update(self, event):
    """Update the slider position."""
    if self.ignore(event) or event.button != 1:
        return

    if event.name == "button_press_event" and event.inaxes == self.ax:
        self.drag_active = True
        event.canvas.grab_mouse(self.ax)

    if not self.drag_active:
        return

    elif (event.name == "button_release_event") or (
        event.name == "button_press_event" and event.inaxes != self.ax
    ):
        self.drag_active = False
        event.canvas.release_mouse(self.ax)
        self._active_handle = None
        return

    # determine which handle was grabbed
    if self.orientation == "vertical":
        handle_index = np.argmin(
            np.abs([h.get_ydata()[0] - event.ydata for h in self._handles])
        )
    else:
        handle_index = np.argmin(
            np.abs([h.get_xdata()[0] - event.xdata for h in self._handles])
        )
    handle = self._handles[handle_index]

    # these checks ensure smooth behavior if the handles swap which one
    # has a higher value. i.e. if one is dragged over and past the other.
    if handle is not self._active_handle:
        self._active_handle = handle

    if self.orientation == "vertical":
        self._update_val_from_pos(event.ydata)
    else:
        self._update_val_from_pos(event.xdata)

def assign_variables(self, data=None, variables={}):
    """Define plot variables, optionally using lookup from `data`."""
    x = variables.get("x", None)
    y = variables.get("y", None)

    if x is None and y is None:
        self.input_format = "wide"
        plot_data, variables = self._assign_variables_wideform(
            data, **variables,
        )
    else:
        self.input_format = "long"
        plot_data, variables = self._assign_variables_longform(
            data, **variables,
        )

    self.plot_data = plot_data
    self.variables = variables
    self.var_types = {
        v: variable_type(
            plot_data[v],
            boolean_type="numeric" if v in "xy" else "categorical"
        )
        for v in variables
    }

    return self

def categorical_mapping(self, data, palette, order):
    """Determine colors when the hue mapping is categorical."""
    # -- Identify the order and name of the levels

    levels = categorical_order(data, order)
    n_colors = len(levels)

    # -- Identify the set of colors to use

    if isinstance(palette, dict):

        missing = set(levels) - set(palette)
        if any(missing):
            err = "The palette dictionary is missing keys: {}"
            raise ValueError(err.format(missing))

        lookup_table = palette

    else:

        if palette is None:
            if n_colors <= len(get_color_cycle()):
                colors = color_palette(None, n_colors)
            else:
                colors = color_palette("husl", n_colors)
        elif isinstance(palette, list):
            if len(palette) != n_colors:
                err = "The palette list has the wrong number of colors."
                raise ValueError(err)
            colors = palette
        else:
            colors = color_palette(palette, n_colors)

        lookup_table = dict(zip(levels, colors))

    return levels, lookup_table

def categorical_order(vector, order=None):
    """Return a list of unique data values.

    Determine an ordered list of levels in ``values``.

    Parameters
    ----------
    vector : list, array, Categorical, or Series
        Vector of "categorical" values
    order : list-like, optional
        Desired order of category levels to override the order determined
        from the ``values`` object.

    Returns
    -------
    order : list
        Ordered list of category levels not including null values.

    """
    if order is None:
        if hasattr(vector, "categories"):
            order = vector.categories
        else:
            try:
                order = vector.cat.categories
            except (TypeError, AttributeError):

                try:
                    order = vector.unique()
                except AttributeError:
                    order = pd.unique(vector)

                if variable_type(vector) == "numeric":
                    order = np.sort(order)

        order = filter(pd.notnull, order)
    return list(order)

def _plot_bivariate(self, x_var, y_var, ax, func, **kwargs):
    """Draw a bivariate plot on the specified axes."""
    if "hue" not in signature(func).parameters:
        self._plot_bivariate_iter_hue(x_var, y_var, ax, func, **kwargs)
        return

    kwargs = kwargs.copy()
    if str(func.__module__).startswith("seaborn"):
        kwargs["ax"] = ax
    else:
        plt.sca(ax)

    if x_var == y_var:
        axes_vars = [x_var]
    else:
        axes_vars = [x_var, y_var]

    if self._hue_var is not None and self._hue_var not in axes_vars:
        axes_vars.append(self._hue_var)

    data = self.data[axes_vars]
    if self._dropna:
        data = data.dropna()

    x = data[x_var]
    y = data[y_var]
    if self._hue_var is None:
        hue = None
    else:
        hue = data.get(self._hue_var)

    if "hue" not in kwargs:
        kwargs.update({
            "hue": hue, "hue_order": self._hue_order, "palette": self._orig_palette,
        })
    func(x=x, y=y, **kwargs)

    self._update_legend_data(ax)

def iter_content(self, chunk_size=1, decode_unicode=False):
    """Iterates over the response data.  When stream=True is set on the
    request, this avoids reading the content at once into memory for
    large responses.  The chunk size is the number of bytes it should
    read into memory.  This is not necessarily the length of each item
    returned as decoding can take place.

    If decode_unicode is True, content will be decoded using the best
    available encoding based on the response.
    """
    def generate():
        try:
            # Special case for urllib3.
            try:
                for chunk in self.raw.stream(chunk_size, decode_content=True):
                    yield chunk
            except IncompleteRead as e:
                raise ChunkedEncodingError(e)
            except DecodeError as e:
                raise ContentDecodingError(e)
        except AttributeError:
            # Standard file-like object.
            while True:
                chunk = self.raw.read(chunk_size)
                if not chunk:
                    break
                yield chunk

        self._content_consumed = True

    # simulate reading small chunks of the content
    reused_chunks = iter_slices(self._content, chunk_size)

    stream_chunks = generate()

    chunks = reused_chunks if self._content_consumed else stream_chunks

    if decode_unicode:
        chunks = stream_decode_response_unicode(chunks, self)

    return chunks

def summarize_coord(name: Hashable, var, col_width: int):
    is_index = name in var.dims
    marker = "*" if is_index else " "
    if is_index:
        coord = var.variable.to_index_variable()
        if coord.level_names is not None:
            return "\n".join(
                [
                    _summarize_coord_multiindex(coord, col_width, marker),
                    _summarize_coord_levels(coord, col_width),
                ]
            )
    return summarize_variable(name, var.variable, col_width, marker)

def summarize_variable(
    name: Hashable, var, col_width: int, marker: str = " ", max_width: int = None
):
    """Summarize a variable in one line, e.g., for the Dataset.__repr__."""
    if max_width is None:
        max_width_options = OPTIONS["display_width"]
        if not isinstance(max_width_options, int):
            raise TypeError(f"`max_width` value of `{max_width}` is not a valid int")
        else:
            max_width = max_width_options
    first_col = pretty_print(f"  {marker} {name} ", col_width)
    if var.dims:
        dims_str = "({}) ".format(", ".join(map(str, var.dims)))
    else:
        dims_str = ""
    front_str = f"{first_col}{dims_str}{var.dtype} "

    values_width = max_width - len(front_str)
    values_str = inline_variable_array_repr(var, values_width)

    return front_str + values_str

def dataset_repr(ds):
    summary = ["<xarray.{}>".format(type(ds).__name__)]

    col_width = _calculate_col_width(_get_col_items(ds.variables))

    dims_start = pretty_print("Dimensions:", col_width)
    summary.append("{}({})".format(dims_start, dim_summary(ds)))

    if ds.coords:
        summary.append(coords_repr(ds.coords, col_width=col_width))

    unindexed_dims_str = unindexed_dims_repr(ds.dims, ds.coords)
    if unindexed_dims_str:
        summary.append(unindexed_dims_str)

    summary.append(data_vars_repr(ds.data_vars, col_width=col_width))

    if ds.attrs:
        summary.append(attrs_repr(ds.attrs))

    return "\n".join(summary)

def _mapping_repr(mapping, title, summarizer, col_width=None):
    if col_width is None:
        col_width = _calculate_col_width(mapping)
    summary = [f"{title}:"]
    if mapping:
        summary += [summarizer(k, v, col_width) for k, v in mapping.items()]
    else:
        summary += [EMPTY_REPR]
    return "\n".join(summary)

def coords_repr(coords, col_width=None):
    if col_width is None:
        col_width = _calculate_col_width(_get_col_items(coords))
    return _mapping_repr(
        coords, title="Coordinates", summarizer=summarize_coord, col_width=col_width
    )

def _regexp_validator(_, name, value):
    if hasattr(value, "pattern"):
        return value
    return re.compile(value)

def _regexp_csv_transfomer(value: str) -> Sequence[Pattern[str]]:
    """Transforms a comma separated list of regular expressions."""
    patterns: list[Pattern[str]] = []
    for pattern in _csv_transformer(value):
        patterns.append(re.compile(pattern))
    return patterns

def _regexp_paths_csv_validator(
    _, name: str, value: str | list[Pattern[str]]
) -> list[Pattern[str]]:
    if isinstance(value, list):
        return value
    patterns = []
    for val in _csv_validator(_, name, value):
        patterns.append(
            re.compile(
                str(pathlib.PureWindowsPath(val)).replace("\\", "\\\\")
                + "|"
                + pathlib.PureWindowsPath(val).as_posix()
            )
        )
    return patterns

def _regexp_paths_csv_transfomer(value: str) -> Sequence[Pattern[str]]:
    """Transforms a comma separated list of regular expressions paths."""
    patterns: list[Pattern[str]] = []
    for pattern in _csv_transformer(value):
        patterns.append(
            re.compile(
                str(pathlib.PureWindowsPath(pattern)).replace("\\", "\\\\")
                + "|"
                + pathlib.PureWindowsPath(pattern).as_posix()
            )
        )
    return patterns

class ColoredLevelFormatter(logging.Formatter):
    """
    Colorize the %(levelname)..s part of the log format passed to __init__.
    """

    LOGLEVEL_COLOROPTS = {
        logging.CRITICAL: {"red"},
        logging.ERROR: {"red", "bold"},
        logging.WARNING: {"yellow"},
        logging.WARN: {"yellow"},
        logging.INFO: {"green"},
        logging.DEBUG: {"purple"},
        logging.NOTSET: set(),
    }
    LEVELNAME_FMT_REGEX = re.compile(r"%\(levelname\)([+-]?\d*s)")

    def __init__(self, terminalwriter, *args, **kwargs):
        super(ColoredLevelFormatter, self).__init__(*args, **kwargs)
        if six.PY2:
            self._original_fmt = self._fmt
        else:
            self._original_fmt = self._style._fmt
        self._level_to_fmt_mapping = {}

        levelname_fmt_match = self.LEVELNAME_FMT_REGEX.search(self._fmt)
        if not levelname_fmt_match:
            return
        levelname_fmt = levelname_fmt_match.group()

        for level, color_opts in self.LOGLEVEL_COLOROPTS.items():
            formatted_levelname = levelname_fmt % {
                "levelname": logging.getLevelName(level)
            }

            # add ANSI escape sequences around the formatted levelname
            color_kwargs = {name: True for name in color_opts}
            colorized_formatted_levelname = terminalwriter.markup(
                formatted_levelname, **color_kwargs
            )
            self._level_to_fmt_mapping[level] = self.LEVELNAME_FMT_REGEX.sub(
                colorized_formatted_levelname, self._fmt
            )

    def format(self, record):
        fmt = self._level_to_fmt_mapping.get(record.levelno, self._original_fmt)
        if six.PY2:
            self._fmt = fmt
        else:
            self._style._fmt = fmt
        return super(ColoredLevelFormatter, self).format(record)

def __str__(self):
    if self._excinfo is None:
        return repr(self)
    entry = self.traceback[-1]
    loc = ReprFileLocation(entry.path, entry.lineno + 1, self.exconly())
    return str(loc)

def path(self) -> Union[py.path.local, str]:
    """ return a path object pointing to source code (or a str in case
    of OSError / non-existing file).
    """
    if not self.raw.co_filename:
        return ""
    try:
        p = py.path.local(self.raw.co_filename)
        # maybe don't try this checking
        if not p.check():
            raise OSError("py.path check failed.")
        return p
    except OSError:
        # XXX maybe try harder like the weird logic
        # in the standard lib [linecache.updatecache] does?
        return self.raw.co_filename

def _makepath(self, path):
    if not self.abspath:
        try:
            np = py.path.local().bestrelpath(path)
        except OSError:
            return path
        if len(np) < len(str(path)):
            path = np
    return path

class FormattedExcinfo:
    """ presenting information about failing Functions and Generators. """

    # for traceback entries
    flow_marker = ">"
    fail_marker = "E"

    showlocals = attr.ib(type=bool, default=False)
    style = attr.ib(type="_TracebackStyle", default="long")
    abspath = attr.ib(type=bool, default=True)
    tbfilter = attr.ib(type=bool, default=True)
    funcargs = attr.ib(type=bool, default=False)
    truncate_locals = attr.ib(type=bool, default=True)
    chain = attr.ib(type=bool, default=True)
    astcache = attr.ib(default=attr.Factory(dict), init=False, repr=False)

    def _getindent(self, source: "Source") -> int:
        # figure out indent for given source
        try:
            s = str(source.getstatement(len(source) - 1))
        except KeyboardInterrupt:
            raise
        except BaseException:
            try:
                s = str(source[-1])
            except KeyboardInterrupt:
                raise
            except BaseException:
                return 0
        return 4 + (len(s) - len(s.lstrip()))

    def _getentrysource(self, entry: TracebackEntry) -> Optional["Source"]:
        source = entry.getsource(self.astcache)
        if source is not None:
            source = source.deindent()
        return source

    def repr_args(self, entry: TracebackEntry) -> Optional["ReprFuncArgs"]:
        if self.funcargs:
            args = []
            for argname, argvalue in entry.frame.getargs(var=True):
                args.append((argname, saferepr(argvalue)))
            return ReprFuncArgs(args)
        return None

    def get_source(
        self,
        source: "Source",
        line_index: int = -1,
        excinfo: Optional[ExceptionInfo] = None,
        short: bool = False,
    ) -> List[str]:
        """ return formatted and marked up source lines. """
        lines = []
        if source is None or line_index >= len(source.lines):
            source = Source("???")
            line_index = 0
        if line_index < 0:
            line_index += len(source)
        space_prefix = "    "
        if short:
            lines.append(space_prefix + source.lines[line_index].strip())
        else:
            for line in source.lines[:line_index]:
                lines.append(space_prefix + line)
            lines.append(self.flow_marker + "   " + source.lines[line_index])
            for line in source.lines[line_index + 1 :]:
                lines.append(space_prefix + line)
        if excinfo is not None:
            indent = 4 if short else self._getindent(source)
            lines.extend(self.get_exconly(excinfo, indent=indent, markall=True))
        return lines

    def get_exconly(
        self, excinfo: ExceptionInfo, indent: int = 4, markall: bool = False
    ) -> List[str]:
        lines = []
        indentstr = " " * indent
        # get the real exception information out
        exlines = excinfo.exconly(tryshort=True).split("\n")
        failindent = self.fail_marker + indentstr[1:]
        for line in exlines:
            lines.append(failindent + line)
            if not markall:
                failindent = indentstr
        return lines

    def repr_locals(self, locals: Dict[str, object]) -> Optional["ReprLocals"]:
        if self.showlocals:
            lines = []
            keys = [loc for loc in locals if loc[0] != "@"]
            keys.sort()
            for name in keys:
                value = locals[name]
                if name == "__builtins__":
                    lines.append("__builtins__ = <builtins>")
                else:
                    # This formatting could all be handled by the
                    # _repr() function, which is only reprlib.Repr in
                    # disguise, so is very configurable.
                    if self.truncate_locals:
                        str_repr = saferepr(value)
                    else:
                        str_repr = safeformat(value)
                    # if len(str_repr) < 70 or not isinstance(value,
                    #                            (list, tuple, dict)):
                    lines.append("{:<10} = {}".format(name, str_repr))
                    # else:
                    #    self._line("%-10s =\\" % (name,))
                    #    # XXX
                    #    pprint.pprint(value, stream=self.excinfowriter)
            return ReprLocals(lines)
        return None

    def repr_traceback_entry(
        self, entry: TracebackEntry, excinfo: Optional[ExceptionInfo] = None
    ) -> "ReprEntry":
        lines = []  # type: List[str]
        style = entry._repr_style if entry._repr_style is not None else self.style
        if style in ("short", "long"):
            source = self._getentrysource(entry)
            if source is None:
                source = Source("???")
                line_index = 0
            else:
                line_index = entry.lineno - entry.getfirstlinesource()
            short = style == "short"
            reprargs = self.repr_args(entry) if not short else None
            s = self.get_source(source, line_index, excinfo, short=short)
            lines.extend(s)
            if short:
                message = "in %s" % (entry.name)
            else:
                message = excinfo and excinfo.typename or ""
            path = self._makepath(entry.path)
            reprfileloc = ReprFileLocation(path, entry.lineno + 1, message)
            localsrepr = self.repr_locals(entry.locals)
            return ReprEntry(lines, reprargs, localsrepr, reprfileloc, style)
        elif style == "value":
            if excinfo:
                lines.extend(str(excinfo.value).split("\n"))
            return ReprEntry(lines, None, None, None, style)
        else:
            if excinfo:
                lines.extend(self.get_exconly(excinfo, indent=4))
            return ReprEntry(lines, None, None, None, style)

    def _makepath(self, path):
        if not self.abspath:
            try:
                np = py.path.local().bestrelpath(path)
            except OSError:
                return path
            if len(np) < len(str(path)):
                path = np
        return path

    def repr_traceback(self, excinfo: ExceptionInfo) -> "ReprTraceback":
        traceback = excinfo.traceback
        if self.tbfilter:
            traceback = traceback.filter()

        if excinfo.errisinstance(RecursionError):
            traceback, extraline = self._truncate_recursive_traceback(traceback)
        else:
            extraline = None

        last = traceback[-1]
        entries = []
        if self.style == "value":
            reprentry = self.repr_traceback_entry(last, excinfo)
            entries.append(reprentry)
            return ReprTraceback(entries, None, style=self.style)

        for index, entry in enumerate(traceback):
            einfo = (last == entry) and excinfo or None
            reprentry = self.repr_traceback_entry(entry, einfo)
            entries.append(reprentry)
        return ReprTraceback(entries, extraline, style=self.style)

    def _truncate_recursive_traceback(
        self, traceback: Traceback
    ) -> Tuple[Traceback, Optional[str]]:
        """
        Truncate the given recursive traceback trying to find the starting point
        of the recursion.

        The detection is done by going through each traceback entry and finding the
        point in which the locals of the frame are equal to the locals of a previous frame (see ``recursionindex()``.

        Handle the situation where the recursion process might raise an exception (for example
        comparing numpy arrays using equality raises a TypeError), in which case we do our best to
        warn the user of the error and show a limited traceback.
        """
        try:
            recursionindex = traceback.recursionindex()
        except Exception as e:
            max_frames = 10
            extraline = (
                "!!! Recursion error detected, but an error occurred locating the origin of recursion.\n"
                "  The following exception happened when comparing locals in the stack frame:\n"
                "    {exc_type}: {exc_msg}\n"
                "  Displaying first and last {max_frames} stack frames out of {total}."
            ).format(
                exc_type=type(e).__name__,
                exc_msg=str(e),
                max_frames=max_frames,
                total=len(traceback),
            )  # type: Optional[str]
            # Type ignored because adding two instaces of a List subtype
            # currently incorrectly has type List instead of the subtype.
            traceback = traceback[:max_frames] + traceback[-max_frames:]  # type: ignore
        else:
            if recursionindex is not None:
                extraline = "!!! Recursion detected (same locals & position)"
                traceback = traceback[: recursionindex + 1]
            else:
                extraline = None

        return traceback, extraline

    def repr_excinfo(self, excinfo: ExceptionInfo) -> "ExceptionChainRepr":
        repr_chain = (
            []
        )  # type: List[Tuple[ReprTraceback, Optional[ReprFileLocation], Optional[str]]]
        e = excinfo.value
        excinfo_ = excinfo  # type: Optional[ExceptionInfo]
        descr = None
        seen = set()  # type: Set[int]
        while e is not None and id(e) not in seen:
            seen.add(id(e))
            if excinfo_:
                reprtraceback = self.repr_traceback(excinfo_)
                reprcrash = (
                    excinfo_._getreprcrash() if self.style != "value" else None
                )  # type: Optional[ReprFileLocation]
            else:
                # fallback to native repr if the exception doesn't have a traceback:
                # ExceptionInfo objects require a full traceback to work
                reprtraceback = ReprTracebackNative(
                    traceback.format_exception(type(e), e, None)
                )
                reprcrash = None

            repr_chain += [(reprtraceback, reprcrash, descr)]
            if e.__cause__ is not None and self.chain:
                e = e.__cause__
                excinfo_ = (
                    ExceptionInfo((type(e), e, e.__traceback__))
                    if e.__traceback__
                    else None
                )
                descr = "The above exception was the direct cause of the following exception:"
            elif (
                e.__context__ is not None and not e.__suppress_context__ and self.chain
            ):
                e = e.__context__
                excinfo_ = (
                    ExceptionInfo((type(e), e, e.__traceback__))
                    if e.__traceback__
                    else None
                )
                descr = "During handling of the above exception, another exception occurred:"
            else:
                e = None
        repr_chain.reverse()
        return ExceptionChainRepr(repr_chain)

def apply(self, **kwargs: Any) -> None:
    # only handle those not otherwise defined in the document
    to_handle = default_substitutions - set(self.document.substitution_defs)
    for ref in self.document.findall(nodes.substitution_reference):
        refname = ref['refname']
        if refname in to_handle:
            text = self.config[refname]
            if refname == 'today' and not text:
                # special handling: can also specify a strftime format
                text = format_date(self.config.today_fmt or _('%b %d, %Y'),
                                   language=self.config.language)
            ref.replace_self(nodes.Text(text))

def apply(self, **kwargs: Any) -> None:
    for node in list(self.document.findall(nodes.target)):
        if not node['ids']:
            continue
        if ('ismod' in node and
                node.parent.__class__ is nodes.section and
                # index 0 is the section title node
                node.parent.index(node) == 1):
            node.parent['ids'][0:0] = node['ids']
            node.parent.remove(node)

def get_module_members(module: Any) -> List[Tuple[str, Any]]:
    """Get members of target module."""
    from sphinx.ext.autodoc import INSTANCEATTR

    warnings.warn('sphinx.ext.autodoc.importer.get_module_members() is deprecated.',
                  RemovedInSphinx50Warning)

    members = {}  # type: Dict[str, Tuple[str, Any]]
    for name in dir(module):
        try:
            value = safe_getattr(module, name, None)
            members[name] = (name, value)
        except AttributeError:
            continue

    # annotation only member (ex. attr: int)
    try:
        for name in getannotations(module):
            if name not in members:
                members[name] = (name, INSTANCEATTR)
    except AttributeError:
        pass

    return sorted(list(members.values()))

def get_object_members(self, want_all: bool) -> Tuple[bool, ObjectMembers]:
    members = self.get_module_members()
    if want_all:
        if not self.__all__:
            # for implicit module members, check __module__ to avoid
            # documenting imported objects
            return True, list(members.values())
        else:
            for member in members.values():
                if member.__name__ not in self.__all__:
                    member.skipped = True

            return False, list(members.values())
    else:
        memberlist = self.options.members or []
        ret = []
        for name in memberlist:
            if name in members:
                ret.append(members[name])
            else:
                logger.warning(__('missing attribute mentioned in :members: option: '
                                  'module %s, attribute %s') %
                               (safe_getattr(self.object, '__name__', '???'), name),
                               type='autodoc')
        return False, ret

def import_object(self, raiseerror: bool = False) -> bool:
    ret = super().import_object(raiseerror)

    try:
        if not self.options.ignore_module_all:
            self.__all__ = inspect.getall(self.object)
    except AttributeError as exc:
        # __all__ raises an error.
        logger.warning(__('%s.__all__ raises an error. Ignored: %r'),
                       (self.fullname, exc), type='autodoc')
    except ValueError as exc:
        # invalid __all__ found.
        logger.warning(__('__all__ should be a list of strings, not %r '
                          '(in module %s) -- ignoring __all__') %
                       (exc.args[0], self.fullname), type='autodoc')

    return ret

class _Empty:
    """A special value for :exclude-members: that never matches to any member."""

    def __contains__(self, item: Any) -> bool:
        return False

def exptrigsimp(expr):
    """
    Simplifies exponential / trigonometric / hyperbolic functions.

    Examples
    ========

    >>> from sympy import exptrigsimp, exp, cosh, sinh
    >>> from sympy.abc import z

    >>> exptrigsimp(exp(z) + exp(-z))
    2*cosh(z)
    >>> exptrigsimp(cosh(z) - sinh(z))
    exp(-z)
    """
    from sympy.simplify.fu import hyper_as_trig, TR2i
    from sympy.simplify.simplify import bottom_up

    def exp_trig(e):
        # select the better of e, and e rewritten in terms of exp or trig
        # functions
        choices = [e]
        if e.has(*_trigs):
            choices.append(e.rewrite(exp))
        choices.append(e.rewrite(cos))
        return min(*choices, key=count_ops)
    newexpr = bottom_up(expr, exp_trig)

    def f(rv):
        if not rv.is_Mul:
            return rv
        rvd = rv.as_powers_dict()
        newd = rvd.copy()

        def signlog(expr, sign=1):
            if expr is S.Exp1:
                return sign, 1
            elif isinstance(expr, exp):
                return sign, expr.args[0]
            elif sign == 1:
                return signlog(-expr, sign=-1)
            else:
                return None, None

        ee = rvd[S.Exp1]
        for k in rvd:
            if k.is_Add and len(k.args) == 2:
                # k == c*(1 + sign*E**x)
                c = k.args[0]
                sign, x = signlog(k.args[1]/c)
                if not x:
                    continue
                m = rvd[k]
                newd[k] -= m
                if ee == -x*m/2:
                    # sinh and cosh
                    newd[S.Exp1] -= ee
                    ee = 0
                    if sign == 1:
                        newd[2*c*cosh(x/2)] += m
                    else:
                        newd[-2*c*sinh(x/2)] += m
                elif newd[1 - sign*S.Exp1**x] == -m:
                    # tanh
                    del newd[1 - sign*S.Exp1**x]
                    if sign == 1:
                        newd[-c/tanh(x/2)] += m
                    else:
                        newd[-c*tanh(x/2)] += m
                else:
                    newd[1 + sign*S.Exp1**x] += m
                    newd[c] += m

        return Mul(*[k**newd[k] for k in newd])
    newexpr = bottom_up(newexpr, f)

    # sin/cos and sinh/cosh ratios to tan and tanh, respectively
    if newexpr.has(HyperbolicFunction):
        e, f = hyper_as_trig(newexpr)
        newexpr = f(TR2i(e))
    if newexpr.has(TrigonometricFunction):
        newexpr = TR2i(newexpr)

    # can we ever generate an I where there was none previously?
    if not (newexpr.has(I) and not expr.has(I)):
        expr = newexpr
    return expr
